rules_version = '2';
service cloud.firestore {
  match /databases/{database}/documents {
    match /c_crc32_little_endian/{doc} {
      allow get: if hashing.crc32('abc') == b'\xc2\x41\x24\x35';
    }
    match /c_crc32_big_endian/{doc} {
      allow get: if hashing.crc32('abc') == b'\x35\x24\x41\xc2';
    }
    match /c_crc32_hex/{doc} {
      allow get: if hashing.crc32('abc').toHexString() == '352441C2';
    }
    match /c_crc32c_hex/{doc} {
      allow get: if hashing.crc32c('abc').toHexString() == '364B3FB7';
    }
    match /c_lower_non_ascii_unchanged/{doc} {
      allow get: if 'É'.lower() == 'É';
    }
    match /c_upper_non_ascii_unchanged/{doc} {
      allow get: if 'é'.upper() == 'é';
    }
    match /c_lower_ascii_mixed/{doc} {
      allow get: if 'AbÉ'.lower() == 'abÉ';
    }
    match /c_index_emoji_utf16/{doc} {
      allow get: if '😀a'[2] == 'a';
    }
    match /c_index_emoji_half/{doc} {
      allow get: if '😀a'[0].size() == 1;
    }
    match /c_split_empty_sep_size_3/{doc} {
      allow get: if 'abc'.split('').size() == 3;
    }
    match /c_split_empty_sep_size_4/{doc} {
      allow get: if 'abc'.split('').size() == 4;
    }
    match /c_split_empty_sep_first/{doc} {
      allow get: if 'abc'.split('')[0] == 'a';
    }
    match /c_split_only_separators/{doc} {
      allow get: if ',,'.split(',').size() == 0;
    }
    match /c_split_empty_sep_first_empty/{doc} {
      allow get: if 'abc'.split('')[0] == '';
    }
    match /c_split_empty_sep_last/{doc} {
      allow get: if 'abc'.split('')[3] == 'c';
    }
    match /c_split_only_separators_1/{doc} {
      allow get: if ',,'.split(',').size() == 1;
    }
    match /c_split_only_separators_3/{doc} {
      allow get: if ',,'.split(',').size() == 3;
    }
    match /c_split_trailing_two_empties/{doc} {
      allow get: if 'a,,'.split(',') == ['a'];
    }
    match /c_split_middle_empty_kept/{doc} {
      allow get: if 'a,,b'.split(',') == ['a', '', 'b'];
    }
    match /c_split_slash_name/{doc} {
      allow get: if 'dir/sub/file.txt'.split('/') == ['dir', 'sub', 'file.txt'];
    }
    match /c_base64_url_md5/{doc} {
      allow get: if hashing.md5(b'abc').toBase64() == 'kAFQmDzST7DWlj99KOF_cg==';
    }
    match /c_diff_added_direction/{doc} {
      allow get: if {'a': 1, 'c': 4}.diff({'a': 1}).addedKeys() == ['c'].toSet();
    }
    match /c_diff_removed_direction/{doc} {
      allow get: if {'a': 1}.diff({'a': 1, 'c': 4}).removedKeys() == ['c'].toSet();
    }
    match /c_int_of_inf_value/{doc} {
      allow get: if int(1.0 / 0.0) == 9223372036854775807;
    }
    match /c_int_of_huge_float_value/{doc} {
      allow get: if int(100000000000000000000.0) == 9223372036854775807;
    }
    match /c_int_of_nan_value/{doc} {
      allow get: if int(0.0 / 0.0) == 0;
    }
    match /c_int_min_div_neg1_value/{doc} {
      allow get: if (-9223372036854775807 - 1) / -1 == -9223372036854775807 - 1;
    }
    match /c_list_eq_int_float_strict/{doc} {
      allow get: if [1.0] == [1.0] && [1] == [1];
    }
    match /c_map_eq_int_float/{doc} {
      allow get: if {'a': 1} == {'a': 1.0};
    }
    match /c_set_eq_int_float/{doc} {
      allow get: if [1].toSet() == [1.0].toSet();
    }
    match /c_neg_zero_in_list/{doc} {
      allow get: if 0.0 in [-0.0];
    }
  }
}

